-- Importação do histórico (Entradas: 2024-10 a 2026-07, Saídas: 2026-02 a 2026-07)
-- Gerado a partir dos exports do sistema fluxodecaixasimples.com.br
-- Idempotente: pode ser rodado mais de uma vez sem duplicar clientes.

-- ---------------------------------------------------------------------------
-- Correções na taxonomia (o seed.sql original, já rodado, não tinha isso)
-- ---------------------------------------------------------------------------

-- "Porcentagem" tem uso real no histórico (35 lançamentos, dezenas de
-- clientes) — reativa caso tenha sido importada como inativa.
update categorias set ativa = true where nome = 'Porcentagem';

-- "Investimento" era usada como categoria de saída antes de existir
-- transferência nativa entre contas — precisa existir para o histórico
-- encaixar, mesmo não sendo o jeito recomendado daqui pra frente.
insert into categorias (grupo_id, nome, ativa)
select gc.id, 'Investimento', true
from grupos_categoria gc
where gc.nome = 'Despesas Operacionais'
  and not exists (select 1 from categorias where nome = 'Investimento');

